81: 	c.scanMu.Lock()
82: 	unlock := true
83: 	defer func() {
84: 		if unlock {
85: 			c.scanMu.Unlock()
86: 		}
87: 	}()
88: 	if c.quiesced || c.intakeClosed.Load() {
89: 		return nil, Fail(409, "RESOURCE_BLOCKED", "runtime intake is fenced")
90: 	}
91: 	if !c.startupComplete {
92: 		if e := c.Recover(ctx); e != nil {
93: 			return nil, e
94: 		}
95: 		c.startupComplete = true
96: 	}
97: 	tx, e := c.service.DB.BeginTx(ctx, nil)
98: 	if e != nil {
99: 		return nil, e
100: 	}
101: 	p, e := authenticate(tx, ownerToken)
102: 	if e != nil {
103: 		tx.Rollback()
104: 		return nil, e
105: 	}
106: 	_, task, e := c.localQualification(tx, p, request)
107: 	if e != nil {
108: 		tx.Rollback()
109: 		return nil, e
110: 	}
111: 	if task["status"] != "DRAFT" {
112: 		tx.Rollback()
113: 		return nil, Fail(409, "STATE_CONFLICT", "qualification already consumed; no automatic retry")
114: 	}
115: 	var route RuntimeCoordinatorRoute
116: 	for _, current := range c.runtimeRoutes() {
117: 		if current.ProjectID == request.ProjectID && current.RuntimeID == request.RuntimeID {
118: 			if route.RuntimeID != "" {
119: 				tx.Rollback()
120: 				return nil, errors.New("ambiguous qualification route")
121: 			}
122: 			route = current
123: 		}
124: 	}
125: 	if route.RuntimeID == "" {
126: 		tx.Rollback()
127: 		return nil, Fail(503, "MODEL_UNAVAILABLE", "prepared route unavailable")
128: 	}
129: 	var active int
130: 	e = tx.QueryRow(`SELECT count(*) FROM domain_objects WHERE project=? AND kind='Run' AND json_extract(body,'$.executor_principal_id')=? AND json_extract(body,'$.status') NOT IN ('SETTLED','FAILED','CANCELLED')`, route.ProjectID, route.ExecutorID).Scan(&active)
131: 	tx.Rollback()
132: 	if e != nil {
133: 		return nil, e
134: 	}
135: 	key := route.ProjectID + "/" + route.ExecutorID
136: 	c.mu.Lock()
137: 	busy := c.active[key]
138: 	c.mu.Unlock()
139: 	if active != 0 || busy {
140: 		return nil, Fail(409, "STATE_CONFLICT", "executor has outstanding work; qualification not started")
141: 	}
142: 	if e = c.authority(ctx, route); e != nil {
