147: 		return nil, e
148: 	}
149: 	c.mu.Lock()
150: 	c.active[key] = true
151: 	c.mu.Unlock()
152: 	c.workers.Add(1)
153: 	c.scanMu.Unlock()
154: 	unlock = false
155: 	defer c.workers.Done()
156: 	defer func() { c.mu.Lock(); delete(c.active, key); c.mu.Unlock() }()
157: 	return run, c.RunAdmitted(ctx, route, run, lease)
